/* Integrated, optional horizon assumptions. No universal decay rate or life simulator. */
(function(root){
'use strict';const $=id=>document.getElementById(id),add=(p,t,text)=>{const e=document.createElement(t);e.textContent=text;p.append(e);return e;};
const benefitNames={now:'Feelings now',connection:'Connection',meaning:'Meaning',security:'Security',health:'Health / stress',flexibility:'Flexibility',other:'Your additional benefit',outcome:'Expected outcome value'};
function controls(parent,prefix,prep=false){const d=add(parent,'details','');d.id=prefix+'TimeEffects';add(d,'summary','Short run vs long run · optional');const label=add(d,'label',''),check=add(label,'input','');check.id=prefix+'TimeEnabled';check.type='checkbox';check.style.width='auto';label.append(document.createTextNode(' Account for an effect changing over time in this score'));add(d,'p','Use this only when you have a reason to expect a particular effect to fade, last or build. It changes an existing benefit criterion, not your money, time or effort costs. Leave it off when unsure.');const fields=add(d,'div','');fields.id=prefix+'TimeFields';fields.hidden=true;
function select(id,title,choices){const l=add(fields,'label',title);l.htmlFor=prefix+id;const el=add(fields,'select','');el.id=l.htmlFor;for(const [value,text] of choices)el.add(new Option(text,value));return el;}
select('TimeKey','Which included benefit changes?',Object.entries(prep?{outcome:benefitNames.outcome}:benefitNames));select('TimeShape','How does its difference between the options change?',[['fade','Fades toward no difference'],['lasting','Lasts at the same size'],['grow','Builds / compounds, up to the score’s cap']]);select('TimeDays','Time window',[['7','One week'],['30','One month (30 days)'],['365','One year (365 days)'],['3650','Ten years (3,650 days)']]).value='30';select('TimeChange','Time for the effect to halve / double',[['1','One day'],['7','One week'],['30','One month'],['365','One year']]).value='7';select('TimeView','What should the headline score use?',[['average','Average effect across the whole period'],['endpoint','Effect remaining at the end']]);add(fields,'p','Other criteria stay fixed. “Average” preserves the experience along the way; “at the end” isolates the remaining effect. The selected rating difference is the starting effect, even when based on learned estimates. This does not change learned success probabilities or automatically model repeated actions.');
check.onchange=()=>{fields.hidden=!check.checked;};$(prefix+'TimeShape').onchange=()=>{$(prefix+'TimeChange').disabled=$(prefix+'TimeShape').value==='lasting';};
const research=add(d,'details','');add(research,'summary','Math and why small choices do not always wash out');add(research,'p','The law of large numbers says averages of suitably independent repeated outcomes tend toward their expectation. It does not force two choices with different expectations to become equal. For 10,000 independent opportunities, a 55% versus 50% success chance gives 5,500 versus 5,000 expected successes. That is an illustrative calculation, not a forecast of your life. A single bounded difference divided across more events can become a smaller share of the average while its absolute consequence remains.');add(research,'p','This score uses exact scenario arithmetic, not thousands of simulated lives. With a starting normalized difference d₀: fading d(t)=d₀ × 2^(−t/h); lasting d(t)=d₀; building d(t)=clip(d₀ × 2^(t/h), −1, 1). The selected effect contributes either d(T) or [integral from 0 to T of d(t) dt]/T to the same weighted tradeoff score. Half-life / doubling time h is your assumption, not inferred from elapsed time or population research. No time discount is added. Growing effects keep their sign and hit the existing ±1 criterion cap.');add(research,'p','A fading effect’s endpoint can approach zero while its accumulated effect remains finite. Life events differ substantially in adaptation; permanent, irreversible, threshold and branching consequences should not be assumed to decay. Costs, explicit later-feelings forecasts, hard limits and refusal overrides are preserved. A curve is a sensitivity scenario, not a causal claim or validated happiness prediction.');
for(const [text,url] of [['Law of large numbers · probability text','https://www.stat.berkeley.edu/~aldous/134/grinstead.pdf'],['Growth, decay and half-life · OpenStax','https://openstax.org/books/calculus-volume-1/pages/6-8-exponential-growth-and-decay'],['Adaptation varies by event · meta-analysis','https://pmc.ncbi.nlm.nih.gov/articles/PMC3289759/']]){const p=add(research,'p',''),a=add(p,'a',text);a.href=url;a.target='_blank';a.rel='noopener';}}
controls($('decisionCustomPriorities')||$('decisionScoreSettings'),'decision');controls($('scoreWeight_income').closest('details'),'income');controls($('prepExtraSettings')||$('prepForm'),'prep',true);
function read(prefix){if(!$(prefix+'TimeEnabled').checked)return undefined;const key=$(prefix+'TimeKey').value;return {version:1,days:Number($(prefix+'TimeDays').value),view:$(prefix+'TimeView').value,effects:{[key]:{shape:$(prefix+'TimeShape').value,changeDays:Number($(prefix+'TimeChange').value)}}};}
function restore(prefix,config){$(prefix+'TimeEnabled').checked=!!config;$(prefix+'TimeFields').hidden=!config;if(!config)return;const [key,e]=Object.entries(config.effects||{})[0]||[];if(!e)return;for(const [id,value] of [['TimeKey',key],['TimeShape',e.shape],['TimeDays',config.days],['TimeChange',e.changeDays],['TimeView',config.view]]){const select=$(prefix+id);if(Array.from(select.options).some(o=>o.value===String(value)))select.value=String(value);}$(prefix+'TimeChange').disabled=e.shape==='lasting';}
function describe(t){return `Time perspective: immediate ${t.immediateScore.toFixed(1)}, period-average ${t.averageScore.toFixed(1)}, end-of-period ${t.endpointScore.toFixed(1)} /100 across ${t.days} days. The headline uses ${t.view==='average'?'the period average':'the endpoint'}. `+t.effects.map(e=>`${e.label}: ${e.initial.toFixed(3)} initially → ${e.endpoint.toFixed(3)} at the end; accumulated ${e.total.toFixed(3)} normalized effect-days (${e.shape}).`).join(' ')+' This is your time-effect scenario. Unmodeled criteria and costs are held fixed; a shared endpoint does not erase earlier experience.';}
root.WamTimeEffects={read,restore,describe};
})(typeof globalThis!=='undefined'?globalThis:this);
